window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e58f2137061c48aa"]={"versions": [{"id": "FIG-e58f2137061c48aa", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation der XML-Schemagenerierung (XML Schema Production Rules) in AUTOSAR. Das Diagramm modelliert den Entscheidungs- und Ableitungsprozess zur Generierung der XML-Repräsentation einer zusammengesetzten Eigenschaft (<code>composite property representation</code>) anhand der Konfiguration von vier booleschen XML-Element-Flags.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangsobjekt / Startzustand</strong>: <code>:Property</code> (M0/M1-Modell-Property bzw. UML-Aggregation Composite).</li>\n<li><strong>Entscheidungsknoten (Decision Node)</strong>: <code>xml. *Element ?</code> zur Auswertung der vier XML-Steuerungsattribute:</li>\n<li><code>xml.roleWrapperElement</code></li>\n<li><code>xml.roleElement</code></li>\n<li><code>xml.typeWrapperElement</code></li>\n<li><code>xml.typeElement</code></li>\n<li><strong>Aktionen / Transformationsschritte</strong>:</li>\n<li><code>[XMLSPR0008] Create composite property representation(1111)</code></li>\n<li><code>[XMLSPR0009] Create composite property representation (1101)</code></li>\n<li><code>[XMLSPR0023] Create composite property representation (1100)</code></li>\n<li><code>[XMLSPR0022] Create composite property representation (1011)</code></li>\n<li><code>[XMLSPR0010] Create composite property representation (1001)</code></li>\n<li><code>[XMLSPR0011] Create composite property representation (0111)</code></li>\n<li><code>[XMLSPR0012] Create composite property representation (0101)</code></li>\n<li><code>[XMLSPR0013] Create composite property representation (0100)</code></li>\n<li><code>[XMLSPR0014] Create composite property representation (0011)</code></li>\n<li><code>[XMLSPR0015] Create composite property representation (0001)</code></li>\n<li><code>[APRXML0016] Create composite property representation (0000)</code></li>\n<li><code>Error</code></li>\n<li><strong>Aktivitätsendknoten (Activity Final Nodes)</strong>: Drei Endknoten (links für linke Aktionen, rechts für rechte Aktionen, mittig für Fehlerpfad).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Eingehend von <code>:Property</code> erreicht der Kontrollfluss den Verzweigungsknoten <code>xml. *Element ?</code>.</li>\n<li>Die Verzweigung prüft die Bitkombination <code>(roleWrapper, role, typeWrapper, type)</code>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[1111]</code>: Übergang zu <code>[XMLSPR0008]</code>, führt zum linken Endknoten.</li>\n<li><code>[1101]</code>: Übergang zu <code>[XMLSPR0009]</code>, führt zum linken Endknoten.</li>\n<li><code>[1100]</code>: Übergang zu <code>[XMLSPR0023]</code>, führt zum linken Endknoten.</li>\n<li><code>[1011]</code>: Übergang zu <code>[XMLSPR0022]</code>, führt zum linken Endknoten.</li>\n<li><code>[1001]</code>: Übergang zu <code>[XMLSPR0010]</code>, führt zum linken Endknoten.</li>\n<li><code>[0111]</code>: Übergang zu <code>[XMLSPR0011]</code>, führt zum rechten Endknoten.</li>\n<li><code>[0101]</code>: Übergang zu <code>[XMLSPR0012]</code>, führt zum rechten Endknoten.</li>\n<li><code>[0100]</code>: Übergang zu <code>[XMLSPR0013]</code>, führt zum rechten Endknoten.</li>\n<li><code>[0011]</code>: Übergang zu <code>[XMLSPR0014]</code>, führt zum rechten Endknoten.</li>\n<li><code>[0001]</code>: Übergang zu <code>[XMLSPR0015]</code>, führt zum rechten Endknoten.</li>\n<li><code>[0000]</code>: Übergang zu <code>[APRXML0016]</code>, führt direkt zum Fehlerknoten oder verbleibt als separater Pfad.</li>\n<li><code>[otherwise]</code>: Führt zur Aktion <code>Error</code> und anschließend zum unteren Endknoten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die normativen Regeln der XML-Schema-Produktion für Composite-Properties. Generatoren für AUTOSAR-XML-Schemata müssen die Kombinationen der vier XML-Stereotypen bzw. Attribute deterministisch auswerten. Nicht abgedeckte oder ungültige Kombinationen führen zwingend in den Fehlerzustand <code>Error</code>.</p>"}, {"id": "FIG-1f2292dd60f7dc4b", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation der XML-Schemagenerierung (XML Schema Production Rules) in AUTOSAR. Das Diagramm modelliert den Entscheidungs- und Ableitungsprozess zur Generierung der XML-Repräsentation einer zusammengesetzten Eigenschaft (<code>composite property representation</code>) anhand der Konfiguration von vier booleschen XML-Element-Flags.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangsobjekt / Startzustand</strong>: <code>:Property</code> (farblich hervorgehoben).</li>\n<li><strong>Entscheidungsknoten (Decision Node)</strong>: <code>xml. *Element ?</code> zur Auswertung der vier XML-Steuerungsattribute:</li>\n<li><code>xml.roleWrapperElement</code></li>\n<li><code>xml.roleElement</code></li>\n<li><code>xml.typeWrapperElement</code></li>\n<li><code>xml.typeElement</code></li>\n<li><strong>Aktionen / Transformationsschritte</strong>:</li>\n<li><code>[TPS_XMLSPR_00008] Create composite property representation(1111)</code></li>\n<li><code>[TPS_XMLSPR_00009] Create composite property representation (1101)</code></li>\n<li><code>[TPS_XMLSPR_00023] Create composite property representation (1100)</code></li>\n<li><code>[TPS_XMLSPR_00022] Create composite property representation (1011)</code></li>\n<li><code>[TPS_XMLSPR_00010] Create composite property representation (1001)</code></li>\n<li><code>[TPS_XMLSPR_00055] Create composite property representation (1000)</code></li>\n<li><code>[TPS_XMLSPR_00011] Create composite property representation (0111)</code></li>\n<li><code>[TPS_XMLSPR_00012] Create composite property representation (0101)</code></li>\n<li><code>[TPS_XMLSPR_00013] Create composite property representation (0100)</code></li>\n<li><code>[TPS_XMLSPR_00014] Create composite property representation (0011)</code></li>\n<li><code>[TPS_XMLSPR_00015] Create composite property representation (0001)</code></li>\n<li><code>[TPS_XMLSPR_00016] Create composite property representation (0000)</code></li>\n<li><code>Error</code></li>\n<li><strong>Aktivitätsendknoten (Activity Final Nodes)</strong>: Drei Endknoten (links, rechts und unterhalb des Fehlerknotens).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Ausgehend von <code>:Property</code> gelangt der Ablauf an den Verzweigungsknoten <code>xml. *Element ?</code>.</li>\n<li>Anhand der Ausprägung der vier booleschen Flags <code>(roleWrapper, role, typeWrapper, type)</code> erfolgt die Verzweigung:</li>\n</ol>\n<ul class=\"fig-list\">\n<li><code>[1111]</code>: Übergang zu <code>[TPS_XMLSPR_00008]</code>, führt in den linken Endknoten.</li>\n<li><code>[1101]</code>: Übergang zu <code>[TPS_XMLSPR_00009]</code>, führt in den linken Endknoten.</li>\n<li><code>[1100]</code>: Übergang zu <code>[TPS_XMLSPR_00023]</code>, führt in den linken Endknoten.</li>\n<li><code>[1011]</code>: Übergang zu <code>[TPS_XMLSPR_00022]</code>, führt in den linken Endknoten.</li>\n<li><code>[1001]</code>: Übergang zu <code>[TPS_XMLSPR_00010]</code>, führt in den linken Endknoten.</li>\n<li><code>[1000]</code>: Übergang zu <code>[TPS_XMLSPR_00055]</code>, führt in den linken Endknoten.</li>\n<li><code>[0111]</code>: Übergang zu <code>[TPS_XMLSPR_00011]</code>, führt in den rechten Endknoten.</li>\n<li><code>[0101]</code>: Übergang zu <code>[TPS_XMLSPR_00012]</code>, führt in den rechten Endknoten.</li>\n<li><code>[0100]</code>: Übergang zu <code>[TPS_XMLSPR_00013]</code>, führt in den rechten Endknoten.</li>\n<li><code>[0011]</code>: Übergang zu <code>[TPS_XMLSPR_00014]</code>, führt in den rechten Endknoten.</li>\n<li><code>[0001]</code>: Übergang zu <code>[TPS_XMLSPR_00015]</code>, führt in den rechten Endknoten.</li>\n<li><code>[0000]</code>: Übergang zu <code>[TPS_XMLSPR_00016]</code>.</li>\n<li><code>[otherwise]</code>: Führt zur Aktion <code>Error</code> und anschließend in den unteren Endknoten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert die normativen Regeln der XML-Schema-Produktion für Composite-Properties nach dem standardisierten Schema <code>TPS_XMLSPR_xxxxx</code>. Generatoren für AUTOSAR-XML-Schemata müssen alle zwölf spezifizierten Bitkombinationen einschließlich des Falls <code>(1000)</code> deterministisch auflösen. Alle nicht explizit abgefangenen Kombinationen fallen unter <code>otherwise</code> und erzeugen einen <code>Error</code>.</p>"}], "trans": [{"from": "FIG-e58f2137061c48aa", "to": "FIG-1f2292dd60f7dc4b", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Neuer Regelfall hinzugefügt: <code>[TPS_XMLSPR_00055] Create composite property representation (1000)</code> mit Guard <code>[xml.roleWrapperElement &amp;&amp; NOT xml.roleElement &amp;&amp; NOT xml.typeWrapperElement &amp;&amp; NOT xml.typeElement]</code>, der in den linken Endzustand mündet.</li>\n<li>Präfixe und Nummerierung der Anforderungs-IDs von Kurzform <code>XMLSPR</code>/<code>APRXML</code> auf standardisiertes Schema <code>TPS_XMLSPR_xxxxx</code> umgestellt (z. B. <code>[XMLSPR0008]</code> zu <code>[TPS_XMLSPR_00008]</code>, <code>[APRXML0016]</code> zu <code>[TPS_XMLSPR_00016]</code>).</li>\n<li>Farbliche Hervorhebung von Startobjekt <code>:Property</code> (hellblau) und Verzweigungsknoten (hellgrün) ergänzt.</li>\n</ul>"}]};
